#!/usr/bin/env python3
"""AI-authored original prompts supported by directly inspected capture excerpts."""
import json
from pathlib import Path
from shorts import graded
ROOT=Path(__file__).resolve().parents[2]
manifest=json.loads((ROOT/'public/data/source-pages.json').read_text())['pages']
reviews=[];questions=[]
def page(n):return f'hanguksa-gichul-page-{n}'
def caps(n):return [{k:c[k] for k in ('src','sha256')} for c in manifest[page(n)]['captures']]
def rev(n,summary,status='content',reason=None):
 r=dict(page=page(n),status=status,captures=caps(n),summary=summary)
 if reason:r['reason']=reason
 reviews.append(r)
def q(n,slug,prompt,answer,quote,location,explain,aliases=()):
 seen={graded(answer)}; a=[]
 for v in aliases:
  if graded(v) not in seen:a.append(v);seen.add(graded(v))
 questions.append(dict(id=f'hanguksa-capture-practice-{n}-{slug}',page=page(n),kind='short',prompt=prompt,answer=answer,acceptedAnswers=a,evidence=[dict(page=page(n),quote=quote)],captureEvidence=[dict(**caps(n)[0],quote=quote,location=location)],explain=explain,topic=answer))
